// SPDX-License-Identifier: LGPL-3.0-or-later
#include "tabulate.h"

#include <string.h>

#include <algorithm>
#include <cassert>

namespace {

template <typename FPTYPE>
struct TableLocation {
  int index;
  FPTYPE offset;
  FPTYPE extrapolation;
};

// Keep the stored sub-table row counts and origins. In particular, rounding a
// width/stride quotient would change the layout of an existing compressed model.
// Clamp the row within its sub-table, including when a quotient at the upper
// edge rounds up or the final interval has a different width from the stride.
template <typename FPTYPE, int NSUB>
inline TableLocation<FPTYPE> locate_table(
    const FPTYPE (&bounds)[NSUB + 1],
    const FPTYPE (&strides)[NSUB],
    const FPTYPE x) {
  const FPTYPE boundary_x = std::max(bounds[0], std::min(x, bounds[NSUB]));
  int row_offset = 0;
  int selected_offset = 0;
  int selected = -1;
  int counts[NSUB];
  for (int ii = 0; ii < NSUB; ++ii) {
    counts[ii] = int((bounds[ii + 1] - bounds[ii]) / strides[ii]);
    if (counts[ii] > 0) {
      selected = ii;
      selected_offset = row_offset;
      if (boundary_x < bounds[ii + 1]) {
        break;
      }
    }
    row_offset += counts[ii];
  }
  // A valid table contains at least one interval; empty sub-tables are allowed.
  assert(selected >= 0);
  const int local_index =
      std::max(0, std::min(int((boundary_x - bounds[selected]) /
                              strides[selected]),
                           counts[selected] - 1));
  const FPTYPE origin = bounds[selected] + local_index * strides[selected];
  return {selected_offset + local_index, boundary_x - origin, x - boundary_x};
}

template <typename FPTYPE>
inline TableLocation<FPTYPE> locate_xx(const FPTYPE lower,
                                       const FPTYPE upper,
                                       const FPTYPE max,
                                       const FPTYPE stride0,
                                       const FPTYPE stride1,
                                       const FPTYPE xx) {
  const FPTYPE bounds[] = {lower, upper, max};
  const FPTYPE strides[] = {stride0, stride1};
  return locate_table(bounds, strides, xx);
}

template <typename FPTYPE>
inline TableLocation<FPTYPE> locate_xx_se_t(const FPTYPE lower,
                                            const FPTYPE upper,
                                            const FPTYPE min,
                                            const FPTYPE max,
                                            const FPTYPE stride0,
                                            const FPTYPE stride1,
                                            const FPTYPE xx) {
  const FPTYPE bounds[] = {min, lower, upper, max};
  const FPTYPE strides[] = {stride1, stride0, stride1};
  return locate_table(bounds, strides, xx);
}

template <typename FPTYPE>
struct TableValue {
  FPTYPE value;
  FPTYPE derivative;
};

// All fused forward, gradient and gradient-gradient kernels use the same
// response. Outside the stored support, continue the endpoint value, slope and
// curvature with a quadratic Taylor polynomial. This gives a C2 continuation
// without extrapolating an unsupported fifth-order polynomial.
template <typename FPTYPE>
inline TableValue<FPTYPE> evaluate_table(const FPTYPE* table,
                                        const int last_layer_size,
                                        const int channel,
                                        const TableLocation<FPTYPE>& location) {
  const FPTYPE* a = table + (location.index * last_layer_size + channel) * 6;
  const FPTYPE x = location.offset;
  FPTYPE value =
      a[0] + (a[1] + (a[2] + (a[3] + (a[4] + a[5] * x) * x) * x) * x) * x;
  FPTYPE derivative =
      a[1] + (2 * a[2] + (3 * a[3] + (4 * a[4] + 5 * a[5] * x) * x) * x) * x;
  if (location.extrapolation != 0) {
    const FPTYPE curvature =
        2 * a[2] + (6 * a[3] + (12 * a[4] + 20 * a[5] * x) * x) * x;
    const FPTYPE delta = location.extrapolation;
    value += delta * (derivative + FPTYPE(0.5) * delta * curvature);
    derivative += delta * curvature;
  }
  return {value, derivative};
}

template <typename FPTYPE>
inline FPTYPE dot(FPTYPE a[4], FPTYPE b[4]) {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2] + a[3] * b[3];
}

}  // namespace

template <typename FPTYPE>
void deepmd::tabulate_fusion_se_a_cpu(FPTYPE* out,
                                      const FPTYPE* table,
                                      const FPTYPE* table_info,
                                      const FPTYPE* em_x,
                                      const FPTYPE* em,
                                      const FPTYPE* two_embed,
                                      const int nloc,
                                      const int nnei,
                                      const int last_layer_size,
                                      const bool is_sorted) {
  bool enable_se_atten = two_embed != nullptr;
  memset(out, 0, sizeof(FPTYPE) * nloc * 4 * last_layer_size);
  const FPTYPE lower = table_info[0];
  const FPTYPE upper = table_info[1];
  const FPTYPE _max = table_info[2];
  const FPTYPE stride0 = table_info[3];
  const FPTYPE stride1 = table_info[4];
// for every atom, execute a small manual gemm ~
// FPTYPE * res = new FPTYPE[4 * last_layer_size];
#pragma omp parallel for
  for (int ii = 0; ii < nloc; ii++) {
    FPTYPE ll[4] = {0};
    FPTYPE ago = em_x[ii * nnei + nnei - 1];
    bool unloop = false;
    for (int jj = 0; jj < nnei; jj++) {
      ll[0] = em[ii * nnei * 4 + jj * 4 + 0];
      ll[1] = em[ii * nnei * 4 + jj * 4 + 1];
      ll[2] = em[ii * nnei * 4 + jj * 4 + 2];
      ll[3] = em[ii * nnei * 4 + jj * 4 + 3];
      FPTYPE xx = em_x[ii * nnei + jj];
      if (ago == xx && ll[1] == 0. && ll[2] == 0. && ll[3] == 0. && is_sorted) {
        unloop = true;
      }
      const auto location =
          locate_xx(lower, upper, _max, stride0, stride1, xx);
      for (int kk = 0; kk < last_layer_size; kk++) {
        const auto polynomial =
            evaluate_table(table, last_layer_size, kk, location);
        FPTYPE var = polynomial.value;
        if (enable_se_atten) {
          FPTYPE t = two_embed[ii * nnei * last_layer_size +
                               jj * last_layer_size + kk];
          var = var * t + var;
        }

        if (unloop) {
          out[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
              (nnei - jj) * var * ll[0];
          out[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
              (nnei - jj) * var * ll[1];
          out[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
              (nnei - jj) * var * ll[2];
          out[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
              (nnei - jj) * var * ll[3];
        } else {
          out[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
              var * ll[0];
          out[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
              var * ll[1];
          out[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
              var * ll[2];
          out[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
              var * ll[3];
        }
      }
      if (unloop) {
        break;
      }
    }
  }
}

