"""Build and run the standalone CPU tabulation regression, entirely offline.

Run: python source/lib/tests/test_tabulate.py
Add --sanitize to enable address and undefined-behavior sanitizers.
"""

import argparse
import os
from pathlib import Path
import shlex
import subprocess
import tempfile


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--sanitize", action="store_true")
    args = parser.parse_args()
    lib = Path(__file__).resolve().parents[1]
    with tempfile.TemporaryDirectory(prefix="tabulate-test-", dir=lib) as build:
        binary = str(Path(build) / "test_tabulate")
        flags = ["-std=c++11", "-O2", "-Wall", "-Wextra",
                 "-Wno-unknown-pragmas", "-Wno-unused-parameter"]
        if args.sanitize:
            flags += ["-O1", "-g", "-fsanitize=address,undefined",
                      "-fno-omit-frame-pointer"]
        command = shlex.split(os.environ.get("CXX", "c++"))
        subprocess.run(command + flags + ["-I", str(lib / "include"),
                       str(lib / "src/tabulate.cc"),
                       str(lib / "tests/test_tabulate.cc"), "-o", binary],
                       check=True)
        subprocess.run([binary], check=True)


if __name__ == "__main__":
    main()
